insert into public.clients (id, business_name, initials, contact_name, email, phone, niche, region, country, timezone, package_name, monthly_fee, lead_target_min, lead_target_max, started_on, billing_day, show_ad_spend, avg_job_value, active) values ('11111111-1111-4111-a111-111111111111', 'Mike''s Plumbing', 'MP', 'Mike', 'demo@leadhivenz.com', '021 555 0192', 'Emergency plumber', 'Auckland', 'NZ', 'Pacific/Auckland', 'Starter', '1500', '15', '25', '2026-06-01', '1', 'false', '450', 'true');
insert into public.months (id, client_id, ym, status, summary, points, published_at) values ('fdeb1933-36a8-4525-ac8b-350cd8fc894b', '11111111-1111-4111-a111-111111111111', '2026-06', 'published', 'First month in and we''re already inside the target range. The campaign is still learning, so expect leads to climb from here as Google works out which searches turn into calls for you.', '[{"title":"Keyword refinement","body":"Adding negative keywords for DIY and price-shopping searches so the budget only goes to people who need a plumber now."},{"title":"Ad copy testing","body":"Running two headline variants to see whether ''same day'' or ''24/7'' pulls more calls."},{"title":"Call hours","body":"Tightening the ad schedule to the hours you answer best."}]'::jsonb, '2026-07-02T06:00:00.000Z');
insert into public.month_private (month_id, ad_spend) values ('fdeb1933-36a8-4525-ac8b-350cd8fc894b', 612);
insert into public.months (id, client_id, ym, status, summary, points, published_at) values ('52daa452-2f4f-487f-a5d7-12810fc740cb', '11111111-1111-4111-a111-111111111111', '2026-07', 'published', 'Up on June, with more calls landing in the afternoon. Missed calls crept up a little; the ones you did answer were strong, mostly blocked drains and hot water.', '[{"title":"Missed call follow-up","body":"4 of 19 calls went unanswered. Each one is a job that probably went to the next plumber on Google. Even a text back within 10 minutes recovers a lot of these."},{"title":"Scaling what''s working","body":"''Blocked drain'' searches are converting best, so I''m moving more of the budget there."},{"title":"Keyword refinement","body":"Weekly search term review, more negatives added."}]'::jsonb, '2026-08-02T06:00:00.000Z');
insert into public.month_private (month_id, ad_spend) values ('52daa452-2f4f-487f-a5d7-12810fc740cb', 688);
insert into public.months (id, client_id, ym, status, summary, points, published_at) values ('0de264e8-3f75-4081-a8bf-71fe556ac548', '11111111-1111-4111-a111-111111111111', '2026-08', 'published', 'Best month yet: 27 leads against a 15 to 25 plan. Hot water cylinder searches picked up with the cold snap and the ads were there for it.', '[{"title":"Scaling what''s working","body":"We cleared the top of the target range, so I''m pushing bids on the hot water and burst pipe terms to hold this volume."},{"title":"Keyword refinement","body":"Added 14 negatives after the search term review. ''Plumbing course'' and ''plumber salary'' were burning clicks."},{"title":"Landing page","body":"Added a hot water cylinder page so those searches land on a page about hot water, not the generic one."}]'::jsonb, '2026-09-02T06:00:00.000Z');
insert into public.month_private (month_id, ad_spend) values ('0de264e8-3f75-4081-a8bf-71fe556ac548', 741);
insert into public.months (id, client_id, ym, status, summary, points, published_at) values ('07e9c7b2-ac53-4451-a740-a919adbb3f04', '11111111-1111-4111-a111-111111111111', '2026-09', 'published', 'A steady month. 22 leads, inside the plan. The one thing to work on is answering: 4 calls went to voicemail or rang out, all between 12 and 2pm. The jobs you tagged as won this month came to $5,750, from a $1,500 plan.', '[{"title":"Missed call follow-up","body":"22% of calls weren''t answered. I''ve shifted the ad schedule so fewer calls land over lunch, but a quick call-back on the missed ones is the easiest money in this report."},{"title":"Scaling what''s working","body":"''Emergency plumber Auckland'' and ''blocked drain'' are still the winners. More budget there, less on the broad ''plumber near me'' term."},{"title":"Keyword refinement","body":"Search term review done weekly. 9 new negatives this month."}]'::jsonb, '2026-10-02T05:00:00.000Z');
insert into public.month_private (month_id, ad_spend) values ('07e9c7b2-ac53-4451-a740-a919adbb3f04', 702);
